CREATE TABLE sync_device(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,actor_id uuid NOT NULL,epoch uuid NOT NULL,name text NOT NULL,status text NOT NULL CHECK(status IN('CHALLENGED','PROVED','ACTIVE','REVOKED')),challenge text NOT NULL,public_key_pem text NOT NULL,fingerprint text NOT NULL,expires_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 0,approved_by uuid,approval_reason text,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,id,epoch),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE sync_recovery_evidence(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,operation_id uuid NOT NULL,source_operation_id uuid NOT NULL,device_id uuid NOT NULL,device_epoch uuid NOT NULL,device_sequence bigint NOT NULL CHECK(device_sequence>0),classification text NOT NULL CHECK(classification IN('COMPLETED_AUTHORIZED','COMPLETED_EXCEPTION')),payload_json text NOT NULL CHECK(length(payload_json)<=250000),payload_hash text NOT NULL CHECK(length(payload_hash)=64),signature_base64 text NOT NULL,reason text NOT NULL,owner_id uuid NOT NULL,received_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('REVIEW_REQUIRED','CONFLICTING_HISTORY')),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,company_id,device_id,device_epoch)REFERENCES sync_device(tenant_id,company_id,id,epoch),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['sync_device','sync_recovery_evidence'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scope_isolation ON %I USING(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch()) WITH CHECK(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())',t);END LOOP;END $$;
GRANT SELECT,INSERT,UPDATE ON sync_device TO quincai_app;GRANT SELECT,INSERT ON sync_recovery_evidence TO quincai_app;
CREATE TRIGGER immutable_recovery BEFORE UPDATE OR DELETE ON sync_recovery_evidence FOR EACH ROW EXECUTE FUNCTION reject_fact_mutation();
